    let canonical = format!("<AnalyticsConfiguration>{content}</AnalyticsConfiguration>");
    let foreign = format!("<AnalyticsConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</AnalyticsConfiguration>");
