fn xml_errors_annotation_table_configuration_updates() {
    let value = dto::AnnotationTableConfigurationUpdates {
        configuration_state: dto::AnnotationConfigurationState::from_static("DISABLED"),
        encryption_configuration: Some(dto::MetadataTableEncryptionConfiguration {
            kms_key_arn: Some(String::from("s3s-xml-sample")),
            sse_algorithm: dto::TableSseAlgorithm::from_static("AES256"),
        }),
        role: Some(String::from("s3s-xml-sample")),
    };
    let content = xml_serialize_content(&value);
    let input = format!("<AnnotationTableConfiguration><S3sUnknown>x</S3sUnknown>{content}</AnnotationTableConfiguration>");
    let ans = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    {
        let input = "<AnnotationTableConfiguration><ConfigurationState>DISABLED</ConfigurationState><ConfigurationState>DISABLED</ConfigurationState></AnnotationTableConfiguration>";
        let err = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<AnnotationTableConfiguration><EncryptionConfiguration><SseAlgorithm>AES256</SseAlgorithm></EncryptionConfiguration><EncryptionConfiguration><SseAlgorithm>AES256</SseAlgorithm></EncryptionConfiguration></AnnotationTableConfiguration>";
        let err = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input =
            "<AnnotationTableConfiguration><Role>s3s-xml-sample</Role><Role>s3s-xml-sample</Role></AnnotationTableConfiguration>";
        let err = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<AnnotationTableConfiguration>{content}</AnnotationTableConfiguration>");
    let foreign =
        format!("<AnnotationTableConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</AnnotationTableConfiguration>");
    let a = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<AnnotationTableConfiguration></AnnotationTableConfiguration>";
        let err = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::MissingField), "empty element: {err:?}, input: {input}");
    }
    {
        let input = "<AnnotationTableConfiguration><Role><S3sNested/></Role></AnnotationTableConfiguration>";
        let err = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedStart),
            "element where text is expected: {err:?}, input: {input}"
        );
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::AnnotationTableConfigurationUpdates>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

