#[test]
fn xml_errors_completed_multipart_upload() {
    let value = dto::CompletedMultipartUpload {
        parts: Some(vec![dto::CompletedPart {
            checksum_crc32: Some(String::from("s3s-xml-sample")),
            checksum_crc32c: Some(String::from("s3s-xml-sample")),
            checksum_crc64nvme: Some(String::from("s3s-xml-sample")),
            checksum_md5: Some(String::from("s3s-xml-sample")),
            checksum_sha1: Some(String::from("s3s-xml-sample")),
            checksum_sha256: Some(String::from("s3s-xml-sample")),
            checksum_sha512: Some(String::from("s3s-xml-sample")),
            checksum_xxhash128: Some(String::from("s3s-xml-sample")),
            checksum_xxhash3: Some(String::from("s3s-xml-sample")),
            checksum_xxhash64: Some(String::from("s3s-xml-sample")),
            e_tag: Some(dto::ETag::Strong(String::from("s3s-xml-sample"))),
            part_number: Some(42),
        }]),
    };
    let content = xml_serialize_content(&value);
    let input = format!("<CompleteMultipartUpload><S3sUnknown>x</S3sUnknown>{content}</CompleteMultipartUpload>");
    let ans = xml_deserialize::<dto::CompletedMultipartUpload>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    let content = xml_serialize_content(&value);
    let canonical = format!("<CompleteMultipartUpload>{content}</CompleteMultipartUpload>");
    let foreign = format!("<CompleteMultipartUpload xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</CompleteMultipartUpload>");
    let a = xml_deserialize::<dto::CompletedMultipartUpload>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::CompletedMultipartUpload>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<CompleteMultipartUpload></CompleteMultipartUpload>";
        let ans = xml_deserialize::<dto::CompletedMultipartUpload>(input.as_bytes());
        assert!(ans.is_ok(), "empty element: {ans:?}, input: {input}");
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::CompletedMultipartUpload>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

