#[test]
fn xml_errors_notification_configuration() {
    let value = dto::NotificationConfiguration {
        event_bridge_configuration: Some(dto::EventBridgeConfiguration {}),
        lambda_function_configurations: Some(vec![dto::LambdaFunctionConfiguration {
            events: vec![dto::Event::from(String::from("s3s-xml-sample"))],
            filter: Some(dto::NotificationConfigurationFilter {
                key: Some(dto::S3KeyFilter {
                    filter_rules: Some(vec![dto::FilterRule {
                        name: Some(dto::FilterRuleName::from_static("prefix")),
                        value: Some(String::from("s3s-xml-sample")),
                    }]),
                }),
            }),
            id: Some(String::from("s3s-xml-sample")),
            lambda_function_arn: String::from("s3s-xml-sample"),
        }]),
        queue_configurations: Some(vec![dto::QueueConfiguration {
            events: vec![dto::Event::from(String::from("s3s-xml-sample"))],
            filter: Some(dto::NotificationConfigurationFilter {
                key: Some(dto::S3KeyFilter {
                    filter_rules: Some(vec![dto::FilterRule {
                        name: Some(dto::FilterRuleName::from_static("prefix")),
                        value: Some(String::from("s3s-xml-sample")),
                    }]),
                }),
            }),
            id: Some(String::from("s3s-xml-sample")),
            queue_arn: String::from("s3s-xml-sample"),
        }]),
        topic_configurations: Some(vec![dto::TopicConfiguration {
            events: vec![dto::Event::from(String::from("s3s-xml-sample"))],
            filter: Some(dto::NotificationConfigurationFilter {
                key: Some(dto::S3KeyFilter {
                    filter_rules: Some(vec![dto::FilterRule {
                        name: Some(dto::FilterRuleName::from_static("prefix")),
                        value: Some(String::from("s3s-xml-sample")),
                    }]),
                }),
            }),
            id: Some(String::from("s3s-xml-sample")),
            topic_arn: String::from("s3s-xml-sample"),
        }]),
    };
    let content = xml_serialize_content(&value);
    let input = format!("<NotificationConfiguration><S3sUnknown>x</S3sUnknown>{content}</NotificationConfiguration>");
    let ans = xml_deserialize::<dto::NotificationConfiguration>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    {
        let input = "<NotificationConfiguration><EventBridgeConfiguration></EventBridgeConfiguration><EventBridgeConfiguration></EventBridgeConfiguration></NotificationConfiguration>";
        let err = xml_deserialize::<dto::NotificationConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<NotificationConfiguration>{content}</NotificationConfiguration>");
    let foreign =
        format!("<NotificationConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</NotificationConfiguration>");
    let a = xml_deserialize::<dto::NotificationConfiguration>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::NotificationConfiguration>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<NotificationConfiguration></NotificationConfiguration>";
        let ans = xml_deserialize::<dto::NotificationConfiguration>(input.as_bytes());
        assert!(ans.is_ok(), "empty element: {ans:?}, input: {input}");
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::NotificationConfiguration>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

