#[test]
fn xml_errors_ownership_controls() {
    let value = dto::OwnershipControls {
        rules: vec![dto::OwnershipControlsRule {
            object_ownership: dto::ObjectOwnership::from_static("BucketOwnerEnforced"),
        }],
    };
    let content = xml_serialize_content(&value);
    let input = format!("<OwnershipControls><S3sUnknown>x</S3sUnknown>{content}</OwnershipControls>");
    let ans = xml_deserialize::<dto::OwnershipControls>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    let content = xml_serialize_content(&value);
    let canonical = format!("<OwnershipControls>{content}</OwnershipControls>");
    let foreign = format!("<OwnershipControls xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</OwnershipControls>");
    let a = xml_deserialize::<dto::OwnershipControls>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::OwnershipControls>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<OwnershipControls></OwnershipControls>";
        let err = xml_deserialize::<dto::OwnershipControls>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::MissingField), "empty element: {err:?}, input: {input}");
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::OwnershipControls>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

