#[test]
fn xml_errors_policy_status() {
    let value = dto::PolicyStatus { is_public: Some(true) };
    {
        let input = "<PolicyStatus><IsPublic>true</IsPublic><IsPublic>true</IsPublic></PolicyStatus>";
        let err = xml_deserialize::<dto::PolicyStatus>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<PolicyStatus>{content}</PolicyStatus>");
    let foreign = format!("<PolicyStatus xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</PolicyStatus>");
    let a = xml_deserialize::<dto::PolicyStatus>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::PolicyStatus>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<PolicyStatus><S3sUnknown>x</S3sUnknown></PolicyStatus>";
        let err = xml_deserialize::<dto::PolicyStatus>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::UnexpectedTagName), "unknown element: {err:?}, input: {input}");
    }
    {
        let input = "<PolicyStatus></PolicyStatus>";
        let ans = xml_deserialize::<dto::PolicyStatus>(input.as_bytes());
        assert!(ans.is_ok(), "empty element: {ans:?}, input: {input}");
    }
    {
        let input = "<PolicyStatus><IsPublic>s3s-not-a-value</IsPublic></PolicyStatus>";
        let err = xml_deserialize::<dto::PolicyStatus>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::InvalidContent),
            "malformed scalar content: {err:?}, input: {input}"
        );
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::PolicyStatus>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

