#[test]
fn xml_errors_public_access_block_configuration() {
    let value = dto::PublicAccessBlockConfiguration {
        block_public_acls: Some(true),
        block_public_policy: Some(true),
        ignore_public_acls: Some(true),
        restrict_public_buckets: Some(true),
    };
    let content = xml_serialize_content(&value);
    let input = format!("<PublicAccessBlockConfiguration><S3sUnknown>x</S3sUnknown>{content}</PublicAccessBlockConfiguration>");
    let ans = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    {
        let input = "<PublicAccessBlockConfiguration><BlockPublicAcls>true</BlockPublicAcls><BlockPublicAcls>true</BlockPublicAcls></PublicAccessBlockConfiguration>";
        let err = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<PublicAccessBlockConfiguration><BlockPublicPolicy>true</BlockPublicPolicy><BlockPublicPolicy>true</BlockPublicPolicy></PublicAccessBlockConfiguration>";
        let err = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<PublicAccessBlockConfiguration><IgnorePublicAcls>true</IgnorePublicAcls><IgnorePublicAcls>true</IgnorePublicAcls></PublicAccessBlockConfiguration>";
        let err = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<PublicAccessBlockConfiguration><RestrictPublicBuckets>true</RestrictPublicBuckets><RestrictPublicBuckets>true</RestrictPublicBuckets></PublicAccessBlockConfiguration>";
        let err = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<PublicAccessBlockConfiguration>{content}</PublicAccessBlockConfiguration>");
    let foreign = format!(
        "<PublicAccessBlockConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</PublicAccessBlockConfiguration>"
    );
    let a = xml_deserialize::<dto::PublicAccessBlockConfiguration>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::PublicAccessBlockConfiguration>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<PublicAccessBlockConfiguration></PublicAccessBlockConfiguration>";
        let ans = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes());
        assert!(ans.is_ok(), "empty element: {ans:?}, input: {input}");
    }
    {
        let input =
            "<PublicAccessBlockConfiguration><BlockPublicAcls>s3s-not-a-value</BlockPublicAcls></PublicAccessBlockConfiguration>";
        let err = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::InvalidContent),
            "malformed scalar content: {err:?}, input: {input}"
        );
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::PublicAccessBlockConfiguration>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

