fn xml_roundtrip_replication_rule() {
    let value = dto::ReplicationRule {
        delete_marker_replication: Some(dto::DeleteMarkerReplication {
            status: Some(dto::DeleteMarkerReplicationStatus::from_static("Disabled")),
        }),
        destination: dto::Destination {
            access_control_translation: Some(dto::AccessControlTranslation {
                owner: dto::OwnerOverride::from_static("Destination"),
            }),
            account: Some(String::from("s3s-xml-sample")),
            bucket: String::from("s3s-xml-sample"),
            encryption_configuration: Some(dto::EncryptionConfiguration {
                replica_kms_key_id: Some(String::from("s3s-xml-sample")),
            }),
            metrics: Some(dto::Metrics {
                event_threshold: Some(dto::ReplicationTimeValue { minutes: Some(42) }),
                status: dto::MetricsStatus::from_static("Disabled"),
            }),
            replication_time: Some(dto::ReplicationTime {
                status: dto::ReplicationTimeStatus::from_static("Disabled"),
                time: dto::ReplicationTimeValue { minutes: Some(42) },
            }),
            storage_class: Some(dto::StorageClass::from_static("AWS_BACKUP_LOW_COST_WARM")),
        },
        existing_object_replication: Some(dto::ExistingObjectReplication {
            status: dto::ExistingObjectReplicationStatus::from_static("Disabled"),
        }),
        filter: Some(dto::ReplicationRuleFilter {
            and: Some(dto::ReplicationRuleAndOperator {
                prefix: Some(String::from("s3s-xml-sample")),
                tags: Some(vec![dto::Tag {
                    key: Some(String::from("s3s-xml-sample")),
                    value: Some(String::from("s3s-xml-sample")),
                }]),
            }),
            prefix: Some(String::from("s3s-xml-sample")),
            tag: Some(dto::Tag {
                key: Some(String::from("s3s-xml-sample")),
                value: Some(String::from("s3s-xml-sample")),
            }),
        }),
        id: Some(String::from("s3s-xml-sample")),
        prefix: Some(String::from("s3s-xml-sample")),
        priority: Some(42),
        source_selection_criteria: Some(dto::SourceSelectionCriteria {
            replica_modifications: Some(dto::ReplicaModifications {
                status: dto::ReplicaModificationsStatus::from_static("Disabled"),
            }),
            sse_kms_encrypted_objects: Some(dto::SseKmsEncryptedObjects {
                status: dto::SseKmsEncryptedObjectsStatus::from_static("Disabled"),
            }),
        }),
        status: dto::ReplicationRuleStatus::from_static("Disabled"),
    };
    let xml = xml_serialize_content(&value);
    assert!(xml.contains("<DeleteMarkerReplication>"), "missing element: {xml}");
    assert!(xml.contains("<Destination>"), "missing element: {xml}");
    assert!(xml.contains("<ExistingObjectReplication>"), "missing element: {xml}");
    assert!(xml.contains("<Filter>"), "missing element: {xml}");
    assert!(xml.contains("<ID>s3s-xml-sample</ID>"), "missing element: {xml}");
    assert!(xml.contains("<Prefix>s3s-xml-sample</Prefix>"), "missing element: {xml}");
    assert!(xml.contains("<Priority>42</Priority>"), "missing element: {xml}");
    assert!(xml.contains("<SourceSelectionCriteria>"), "missing element: {xml}");
    assert!(xml.contains("<Status>Disabled</Status>"), "missing element: {xml}");
    let parsed = xml_deserialize_content::<dto::ReplicationRule>(xml.as_bytes()).unwrap();
    assert!(parsed == value, "xml round trip mismatch: {xml}");
}

#[cfg(not(feature = "minio"))]
#[test]
fn xml_errors_replication_rule() {
    {
        let input = "<DeleteMarkerReplication></DeleteMarkerReplication><DeleteMarkerReplication></DeleteMarkerReplication>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Destination><Bucket>s3s-xml-sample</Bucket></Destination><Destination><Bucket>s3s-xml-sample</Bucket></Destination>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<ExistingObjectReplication><Status>Disabled</Status></ExistingObjectReplication><ExistingObjectReplication><Status>Disabled</Status></ExistingObjectReplication>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Filter></Filter><Filter></Filter>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<ID>s3s-xml-sample</ID><ID>s3s-xml-sample</ID>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Prefix>s3s-xml-sample</Prefix><Prefix>s3s-xml-sample</Prefix>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Priority>42</Priority><Priority>42</Priority>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<SourceSelectionCriteria></SourceSelectionCriteria><SourceSelectionCriteria></SourceSelectionCriteria>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Status>Disabled</Status><Status>Disabled</Status>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<S3sUnknown>x</S3sUnknown>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::UnexpectedTagName), "unknown element: {err:?}, input: {input}");
    }
    {
        let input = "";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::MissingField), "empty element: {err:?}, input: {input}");
    }
    {
        let input = "<ID><S3sNested/></ID>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedStart),
            "element where text is expected: {err:?}, input: {input}"
        );
    }
    {
        let input = "<Priority>s3s-not-a-value</Priority>";
        let err = xml_deserialize_content::<dto::ReplicationRule>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::InvalidContent),
            "malformed scalar content: {err:?}, input: {input}"
        );
    }
}

