#[test]
fn xml_errors_request_payment_configuration() {
    let value = dto::RequestPaymentConfiguration {
        payer: dto::Payer::from_static("BucketOwner"),
    };
    let content = xml_serialize_content(&value);
    let input = format!("<RequestPaymentConfiguration><S3sUnknown>x</S3sUnknown>{content}</RequestPaymentConfiguration>");
    let ans = xml_deserialize::<dto::RequestPaymentConfiguration>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    {
        let input =
            "<RequestPaymentConfiguration><Payer>BucketOwner</Payer><Payer>BucketOwner</Payer></RequestPaymentConfiguration>";
        let err = xml_deserialize::<dto::RequestPaymentConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<RequestPaymentConfiguration>{content}</RequestPaymentConfiguration>");
    let foreign =
        format!("<RequestPaymentConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</RequestPaymentConfiguration>");
    let a = xml_deserialize::<dto::RequestPaymentConfiguration>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::RequestPaymentConfiguration>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<RequestPaymentConfiguration></RequestPaymentConfiguration>";
        let err = xml_deserialize::<dto::RequestPaymentConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::MissingField), "empty element: {err:?}, input: {input}");
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::RequestPaymentConfiguration>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

