#[test]
fn xml_errors_server_side_encryption_configuration() {
    let value = dto::ServerSideEncryptionConfiguration {
        rules: vec![dto::ServerSideEncryptionRule {
            apply_server_side_encryption_by_default: Some(dto::ServerSideEncryptionByDefault {
                kms_master_key_id: Some(String::from("s3s-xml-sample")),
                sse_algorithm: dto::ServerSideEncryption::from_static("AES256"),
            }),
            blocked_encryption_types: Some(dto::BlockedEncryptionTypes {
                encryption_type: Some(vec![dto::EncryptionType::from_static("NONE")]),
            }),
            bucket_key_enabled: Some(true),
        }],
    };
    let content = xml_serialize_content(&value);
    let input =
        format!("<ServerSideEncryptionConfiguration><S3sUnknown>x</S3sUnknown>{content}</ServerSideEncryptionConfiguration>");
    let ans = xml_deserialize::<dto::ServerSideEncryptionConfiguration>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    let content = xml_serialize_content(&value);
    let canonical = format!("<ServerSideEncryptionConfiguration>{content}</ServerSideEncryptionConfiguration>");
    let foreign = format!(
        "<ServerSideEncryptionConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</ServerSideEncryptionConfiguration>"
    );
    let a = xml_deserialize::<dto::ServerSideEncryptionConfiguration>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::ServerSideEncryptionConfiguration>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<ServerSideEncryptionConfiguration></ServerSideEncryptionConfiguration>";
        let err = xml_deserialize::<dto::ServerSideEncryptionConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::MissingField), "empty element: {err:?}, input: {input}");
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::ServerSideEncryptionConfiguration>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

