#[test]
fn xml_errors_stats() {
    let value = dto::Stats {
        bytes_processed: Some(42),
        bytes_returned: Some(42),
        bytes_scanned: Some(42),
    };
    {
        let input = "<Stats><BytesProcessed>42</BytesProcessed><BytesProcessed>42</BytesProcessed></Stats>";
        let err = xml_deserialize::<dto::Stats>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Stats><BytesReturned>42</BytesReturned><BytesReturned>42</BytesReturned></Stats>";
        let err = xml_deserialize::<dto::Stats>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<Stats><BytesScanned>42</BytesScanned><BytesScanned>42</BytesScanned></Stats>";
        let err = xml_deserialize::<dto::Stats>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<Stats>{content}</Stats>");
    let foreign = format!("<Stats xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</Stats>");
    let a = xml_deserialize::<dto::Stats>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::Stats>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<Stats><S3sUnknown>x</S3sUnknown></Stats>";
        let err = xml_deserialize::<dto::Stats>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::UnexpectedTagName), "unknown element: {err:?}, input: {input}");
    }
    {
        let input = "<Stats></Stats>";
        let ans = xml_deserialize::<dto::Stats>(input.as_bytes());
        assert!(ans.is_ok(), "empty element: {ans:?}, input: {input}");
    }
    {
        let input = "<Stats><BytesProcessed>s3s-not-a-value</BytesProcessed></Stats>";
        let err = xml_deserialize::<dto::Stats>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::InvalidContent),
            "malformed scalar content: {err:?}, input: {input}"
        );
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::Stats>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

