#[cfg(not(feature = "minio"))]
#[test]
fn xml_errors_versioning_configuration() {
    let value = dto::VersioningConfiguration {
        mfa_delete: Some(dto::MFADelete::from_static("Disabled")),
        status: Some(dto::BucketVersioningStatus::from_static("Enabled")),
    };
    let content = xml_serialize_content(&value);
    let input = format!("<VersioningConfiguration><S3sUnknown>x</S3sUnknown>{content}</VersioningConfiguration>");
    let ans = xml_deserialize::<dto::VersioningConfiguration>(input.as_bytes());
    assert!(ans.is_ok(), "unknown element: {ans:?}, input: {input}");
    {
        let input =
            "<VersioningConfiguration><MfaDelete>Disabled</MfaDelete><MfaDelete>Disabled</MfaDelete></VersioningConfiguration>";
        let err = xml_deserialize::<dto::VersioningConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    {
        let input = "<VersioningConfiguration><Status>Enabled</Status><Status>Enabled</Status></VersioningConfiguration>";
        let err = xml_deserialize::<dto::VersioningConfiguration>(input.as_bytes()).unwrap_err();
        assert!(matches!(err, xml::DeError::DuplicateField), "duplicate field: {err:?}, input: {input}");
    }
    let content = xml_serialize_content(&value);
    let canonical = format!("<VersioningConfiguration>{content}</VersioningConfiguration>");
    let foreign = format!("<VersioningConfiguration xmlns=\"urn:s3s-not-the-s3-namespace\">{content}</VersioningConfiguration>");
    let a = xml_deserialize::<dto::VersioningConfiguration>(canonical.as_bytes()).unwrap();
    let b = xml_deserialize::<dto::VersioningConfiguration>(foreign.as_bytes()).unwrap();
    assert!(a == b, "a foreign namespace changed the parsed value");
    {
        let input = "<VersioningConfiguration></VersioningConfiguration>";
        let ans = xml_deserialize::<dto::VersioningConfiguration>(input.as_bytes());
        assert!(ans.is_ok(), "empty element: {ans:?}, input: {input}");
    }
    {
        let input = "<S3sWrongRoot></S3sWrongRoot>";
        let err = xml_deserialize::<dto::VersioningConfiguration>(input.as_bytes()).unwrap_err();
        assert!(
            matches!(err, xml::DeError::UnexpectedTagName),
            "wrong root element name: {err:?}, input: {input}"
        );
    }
}

