#[test]
fn xml_roundtrip_website_configuration() {
    let value = dto::WebsiteConfiguration {
        error_document: Some(dto::ErrorDocument {
            key: String::from("s3s-xml-sample"),
        }),
        index_document: Some(dto::IndexDocument {
            suffix: String::from("s3s-xml-sample"),
        }),
        redirect_all_requests_to: Some(dto::RedirectAllRequestsTo {
            host_name: String::from("s3s-xml-sample"),
            protocol: Some(dto::Protocol::from_static("http")),
        }),
        routing_rules: Some(vec![dto::RoutingRule {
            condition: Some(dto::Condition {
                http_error_code_returned_equals: Some(String::from("s3s-xml-sample")),
                key_prefix_equals: Some(String::from("s3s-xml-sample")),
            }),
            redirect: dto::Redirect {
                host_name: Some(String::from("s3s-xml-sample")),
                http_redirect_code: Some(String::from("s3s-xml-sample")),
                protocol: Some(dto::Protocol::from_static("http")),
                replace_key_prefix_with: Some(String::from("s3s-xml-sample")),
                replace_key_with: Some(String::from("s3s-xml-sample")),
            },
        }]),
    };
    let xml = xml_serialize(&value);
    assert!(xml.starts_with("<WebsiteConfiguration>"), "root element: {xml}");
    assert!(xml.ends_with("</WebsiteConfiguration>"), "root element: {xml}");
    assert!(xml.contains("<ErrorDocument>"), "missing element: {xml}");
    assert!(xml.contains("<IndexDocument>"), "missing element: {xml}");
    assert!(xml.contains("<RedirectAllRequestsTo>"), "missing element: {xml}");
    assert!(xml.contains("<RoutingRules>"), "missing element: {xml}");
    let parsed = xml_deserialize::<dto::WebsiteConfiguration>(xml.as_bytes()).unwrap();
    assert!(parsed == value, "xml round trip mismatch: {xml}");
}

